#include "document.h"

/* PNG */
static const wxString s_document_16_png = wxT("");

wxIcon ibValueMetaObjectDocument::GetIcon() const
{
	return GetIconGroup();
}

wxIcon ibValueMetaObjectDocument::GetIconGroup()
{
	static wxIcon icon =
		ibBackendPicture::GetIconFromBase64(s_document_16_png, wxSize(16, 16));

	return icon;
}
